    WHERE id = v_lesson_id;
    
    RAISE NOTICE 'Updated lesson: Before You Reply';
  END IF;

END $$;


-- Insert Quiz Questions for Lesson: Before You Reply

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 4 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 4 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'before-you-reply' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson before-you-reply not found in module 4';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why is it important to check if someone already booked an appointment?', 
    '["To cancel their appointment","To avoid asking them to book again, which looks unprofessional","To reschedule without telling them","It''s not important"]'::jsonb,
    'To avoid asking them to book again, which looks unprofessional',
    'Asking someone to book when they already have an appointment shows you don''t know your own business. Always check existing appointments first.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you do before replying to a message?', 
    '["Reply immediately with the first thing that comes to mind","Read the full thread, check contact details, and decide the next step","Delete the message","Forward it to someone else"]'::jsonb,
    'Read the full thread, check contact details, and decide the next step',
    'Taking a moment to understand the full context helps you write a more effective reply that moves the conversation forward.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why should you check if automation already sent messages?', 
    '["To delete the automation","To avoid repeating information the contact already received","To turn off all automation","It''s not necessary to check"]'::jsonb,
    'To avoid repeating information the contact already received',
    'If automation already sent a booking link or information, you don''t want to confuse the contact by sending it again. Check what they''ve already received.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
